func TestRender(t *testing.T) {
	tests := []struct {
		name string
		rows []string
		want []string
	}{
		{"empty", []string{}, []string{}},
		{"single", []string{"only"}, []string{}},
		{"two", []string{"first", "second"}, []string{"second"}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			got := Render("alice", tc.rows)
			if len(got) != len(tc.want) {
				t.Fatalf("got %v, want %v", got, tc.want)
			}
			for i := range got {
				if got[i] != tc.want[i] {
					t.Fatalf("got %v, want %v", got, tc.want)
				}
			}
		})
	}
}

